#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mPts;
uniform float amzp_mBlack;
uniform float2 amzp_m1;
uniform float2 amzp_m2;
uniform float2 amzp_m3;
uniform float2 amzp_m4;
uniform float2 amzp_m5;
uniform float2 amzp_m6;
uniform float2 amzp_m7;
uniform float2 amzp_m8;
uniform float amzp_mWhite;
uniform float amzp_rPts;
uniform float amzp_rBlack;
uniform float2 amzp_r1;
uniform float2 amzp_r2;
uniform float2 amzp_r3;
uniform float2 amzp_r4;
uniform float2 amzp_r5;
uniform float2 amzp_r6;
uniform float2 amzp_r7;
uniform float2 amzp_r8;
uniform float amzp_rWhite;
uniform float amzp_gPts;
uniform float amzp_gBlack;
uniform float2 amzp_g1;
uniform float2 amzp_g2;
uniform float2 amzp_g3;
uniform float2 amzp_g4;
uniform float2 amzp_g5;
uniform float2 amzp_g6;
uniform float2 amzp_g7;
uniform float2 amzp_g8;
uniform float amzp_gWhite;
uniform float amzp_bPts;
uniform float amzp_bBlack;
uniform float2 amzp_b1;
uniform float2 amzp_b2;
uniform float2 amzp_b3;
uniform float2 amzp_b4;
uniform float2 amzp_b5;
uniform float2 amzp_b6;
uniform float2 amzp_b7;
uniform float2 amzp_b8;
uniform float amzp_bWhite;
uniform float amzp_mixAmt;
    float herm(float x, float xa, float xb, float ya, float yb, float ma, float mb) {
        float h = xb - xa;
        float t = clamp((x - xa) / h, 0.0, 1.0);
        float t2 = t * t, t3 = t2 * t;
        return (2.0 * t3 - 3.0 * t2 + 1.0) * ya + (t3 - 2.0 * t2 + t) * h * ma + (-2.0 * t3 + 3.0 * t2) * yb + (t3 - t2) * h * mb;
    }
    float tan3(float d0, float d1, float h0, float h1) {
        if (d0 * d1 <= 0.0) return 0.0;
        float w1 = 2.0 * h1 + h0, w2 = h1 + 2.0 * h0;
        return (w1 + w2) / (w1 / d0 + w2 / d1);
    }
    bool isFlat(float yb, float yw, float cnt, float2 q1, float2 q2, float2 q3, float2 q4, float2 q5, float2 q6, float2 q7, float2 q8) {
        float n = clamp(floor(cnt + 0.5), 1.0, 8.0);
        float d = abs(yb) + abs(yw - 1.0) + abs(q1.y - q1.x);
        if (n > 1.5) d += abs(q2.y - q2.x);
        if (n > 2.5) d += abs(q3.y - q3.x);
        if (n > 3.5) d += abs(q4.y - q4.x);
        if (n > 4.5) d += abs(q5.y - q5.x);
        if (n > 5.5) d += abs(q6.y - q6.x);
        if (n > 6.5) d += abs(q7.y - q7.x);
        if (n > 7.5) d += abs(q8.y - q8.x);
        return d < 0.0001;
    }
    float3 curve(float3 x, float yb, float yw, float cnt, float2 q1, float2 q2, float2 q3, float2 q4, float2 q5, float2 q6, float2 q7, float2 q8) {
        int n = int(clamp(floor(cnt + 0.5), 1.0, 8.0));
        float2 P[8];
        P[0] = q1; P[1] = q2; P[2] = q3; P[3] = q4; P[4] = q5; P[5] = q6; P[6] = q7; P[7] = q8;
        for (int i = 0; i < 7; i++) {
            if (i + 1 >= n) break;
            for (int j = 0; j < 7; j++) {
                if (j + 1 < n - i && P[j].x > P[j + 1].x) { float2 t = P[j]; P[j] = P[j + 1]; P[j + 1] = t; }
            }
        }
        float X[11];
        float Y[11];
        for (int k = 0; k < 11; k++) { X[k] = 1.0; Y[k] = yw; }
        X[0] = 0.0; Y[0] = yb;
        float prev = 0.0;
        for (int k = 0; k < 8; k++) {
            if (k >= n) break;
            float lo = (k == 0) ? 0.01 : prev + 0.01;
            float hi = 0.99 - 0.01 * float(n - 1 - k);
            float xk = clamp(P[k].x, lo, max(hi, lo));
            X[k + 1] = xk;
            Y[k + 1] = P[k].y;
            prev = xk;
        }
        int m = n + 2;
        x = clamp(x, 0.0, 1.0);
        float3 res = float3(yw);
        float3 done = float3(0.0);
        float dPrev = 0.0, hPrev = 1.0;
        for (int k = 0; k < 9; k++) {
            if (k >= m - 1) break;
            float h = max(X[k + 1] - X[k], 1e-4);
            float d = (Y[k + 1] - Y[k]) / h;
            float dNext = d, hNext = h;
            if (k + 1 < m - 1) { hNext = max(X[k + 2] - X[k + 1], 1e-4); dNext = (Y[k + 2] - Y[k + 1]) / hNext; }
            float ma = (k == 0) ? d : tan3(dPrev, d, hPrev, h);
            float mb = (k + 1 >= m - 1) ? d : tan3(d, dNext, h, hNext);
            bool last = k == m - 2;
            if (done.x < 0.5 && (x.x <= X[k + 1] || last)) { res.x = herm(x.x, X[k], X[k + 1], Y[k], Y[k + 1], ma, mb); done.x = 1.0; }
            if (done.y < 0.5 && (x.y <= X[k + 1] || last)) { res.y = herm(x.y, X[k], X[k + 1], Y[k], Y[k + 1], ma, mb); done.y = 1.0; }
            if (done.z < 0.5 && (x.z <= X[k + 1] || last)) { res.z = herm(x.z, X[k], X[k + 1], Y[k], Y[k + 1], ma, mb); done.z = 1.0; }
            if (done.x + done.y + done.z > 2.5) break;
            dPrev = d; hPrev = h;
        }
        return clamp(res, 0.0, 1.0);
    }
    void amzRender() {
        float4 src = amzTexture(0, amzScreenNorm());
        bool fm = isFlat(amzp_mBlack, amzp_mWhite, amzp_mPts, amzp_m1, amzp_m2, amzp_m3, amzp_m4, amzp_m5, amzp_m6, amzp_m7, amzp_m8), fr = isFlat(amzp_rBlack, amzp_rWhite, amzp_rPts, amzp_r1, amzp_r2, amzp_r3, amzp_r4, amzp_r5, amzp_r6, amzp_r7, amzp_r8), fg = isFlat(amzp_gBlack, amzp_gWhite, amzp_gPts, amzp_g1, amzp_g2, amzp_g3, amzp_g4, amzp_g5, amzp_g6, amzp_g7, amzp_g8), fb = isFlat(amzp_bBlack, amzp_bWhite, amzp_bPts, amzp_b1, amzp_b2, amzp_b3, amzp_b4, amzp_b5, amzp_b6, amzp_b7, amzp_b8);
        if ((fm && fr && fg && fb) || amzp_mixAmt <= 0.0001 || src.a <= 0.0001) { amzOutput = src; return; }
        float3 c = src.rgb / src.a;
        float3 y = c;
        if (!fm) y = curve(c, amzp_mBlack, amzp_mWhite, amzp_mPts, amzp_m1, amzp_m2, amzp_m3, amzp_m4, amzp_m5, amzp_m6, amzp_m7, amzp_m8);
        if (!fr) y.r = curve(float3(y.r), amzp_rBlack, amzp_rWhite, amzp_rPts, amzp_r1, amzp_r2, amzp_r3, amzp_r4, amzp_r5, amzp_r6, amzp_r7, amzp_r8).x;
        if (!fg) y.g = curve(float3(y.g), amzp_gBlack, amzp_gWhite, amzp_gPts, amzp_g1, amzp_g2, amzp_g3, amzp_g4, amzp_g5, amzp_g6, amzp_g7, amzp_g8).x;
        if (!fb) y.b = curve(float3(y.b), amzp_bBlack, amzp_bWhite, amzp_bPts, amzp_b1, amzp_b2, amzp_b3, amzp_b4, amzp_b5, amzp_b6, amzp_b7, amzp_b8).x;
        float3 o = mix(c, y, clamp(amzp_mixAmt, 0.0, 1.0));
        amzOutput = float4(clamp(o, 0.0, 1.0) * src.a, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
